# Both small dolls are retained; coordinated motion reduces budget use and keeps their paths separate.
# Move the left doll toward its slot while lifting the right doll above all standing neighbors.
def dual_move(lp, rp, lg, rg, count, guard_left=None, guard_right=None):
    obs = get_observation()
    ls = obs['state']['left_ee_pose'].copy()
    rs = obs['state']['right_ee_pose'].copy()
    for i in range(count):
        f = min(1.0, (i+1)/max(1,count-3))
        lq = (1-f)*ls[3:] + f*np.array(lp[3:]); lq = lq/np.linalg.norm(lq)
        rq = (1-f)*rs[3:] + f*np.array(rp[3:]); rq = rq/np.linalg.norm(rq)
        la = list((1-f)*ls[:3]+f*np.array(lp[:3])) + list(lq)
        ra = list((1-f)*rs[:3]+f*np.array(rp[:3])) + list(rq)
        obs, reward, terminated, truncated, info = step({'left_ee_pose':la,'right_ee_pose':ra,'left_ee_joint_state':[lg],'right_ee_joint_state':[rg]})
        if terminated or truncated:
            return {'stopped':'episode','steps':i+1}
        if guard_left is not None and obs['state']['left_ee_joint_state'][0] < guard_left:
            return {'stopped':'left_grasp_lost','steps':i+1}
        if guard_right is not None and obs['state']['right_ee_joint_state'][0] < guard_right:
            return {'stopped':'right_grasp_lost','steps':i+1}
    return {'stopped':'done','left_error':float(np.linalg.norm(obs['state']['left_ee_pose'][:3]-np.array(lp[:3]))),'right_error':float(np.linalg.norm(obs['state']['right_ee_pose'][:3]-np.array(rp[:3])))}
